use xiom.io;
fn main() -> Int {
  let phonebook: Map[Str,Str] = Map[Str,Str].new();
  phonebook.insert("Mom", "555-0100");
  phonebook.insert("Dad", "555-0200");

  match phonebook.get("Mom") {
    Some(num) => io.println(num.to_str());
    None => io.println("Not found");
  }

  match phonebook.get("Stranger") {
    Some(num) => io.println(num.to_str());
    None => io.println("Not found");
  }

  return 0;
}
